import React, { useState } from 'react';

const QuanLyThongBaoCuDan = () => {
    const [activeTab, setActiveTab] = useState('chung');

    return (
        <div style={styles.container}>
            <div style={styles.header}>
                <h2 style={{color: '#2e7d32'}}>🔔 Trung tâm thông báo</h2>
                <p style={{color: '#666'}}>Cập nhật những tin tức mới nhất từ Ban quản lý</p>
            </div>

            <div style={styles.tabContainer}>
                <button onClick={() => setActiveTab('chung')} style={{...styles.tab, borderBottom: activeTab === 'chung' ? '3px solid #2e7d32' : 'none'}}>Bảng tin tòa nhà</button>
                <button onClick={() => setActiveTab('rieng')} style={{...styles.tab, borderBottom: activeTab === 'rieng' ? '3px solid #2e7d32' : 'none'}}>Phản hồi của tôi</button>
            </div>

            {activeTab === 'chung' ? (
                <div style={styles.list}>
                    <div style={styles.newsCard}>
                        <span style={styles.newBadge}>MỚI</span>
                        <h4>Thông báo cắt nước bảo trì định kỳ</h4>
                        <p style={styles.newsDate}>Đăng bởi: Ban Quản Lý | 17/04/2026</p>
                        <p style={styles.newsPreview}>Để phục vụ công tác bảo trì hệ thống nước sạch định kỳ, tòa nhà sẽ tạm ngưng cung cấp nước...</p>
                        <button style={styles.readMore}>Xem toàn bộ thông báo</button>
                    </div>
                </div>
            ) : (
                <div style={styles.formCard}>
                    <h3>Gửi ý kiến / Khiếu nại cho Admin</h3>
                    <input type="text" placeholder="Chủ đề (Vd: Báo hỏng đèn hành lang...)" style={styles.input} />
                    <textarea placeholder="Mô tả chi tiết vấn đề bạn đang gặp phải..." style={styles.textarea}></textarea>
                    <button style={styles.submitBtn}>Gửi phản hồi</button>
                </div>
            )}
        </div>
    );
};

// Copy Styles tương tự như file trên nhưng chỉnh màu nhẹ nhàng hơn cho cư dân
const styles = {
    container: { padding: '20px' },
    header: { marginBottom: '30px' },
    tabContainer: { display: 'flex', gap: '30px', borderBottom: '1px solid #ddd', marginBottom: '25px' },
    tab: { padding: '10px 5px', background: 'none', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '16px' },
    newsCard: { backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)', borderLeft: '5px solid #2e7d32' },
    newBadge: { backgroundColor: '#ff4d4f', color: '#fff', padding: '2px 8px', borderRadius: '4px', fontSize: '11px', fontWeight: 'bold' },
    newsDate: { fontSize: '12px', color: '#999', margin: '5px 0' },
    newsPreview: { color: '#444', lineHeight: '1.6' },
    readMore: { background: 'none', border: 'none', color: '#2e7d32', fontWeight: 'bold', cursor: 'pointer', marginTop: '10px', padding: 0 },
    formCard: { backgroundColor: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' },
    input: { width: '100%', padding: '12px', marginBottom: '15px', borderRadius: '8px', border: '1px solid #ddd' },
    textarea: { width: '100%', padding: '12px', height: '100px', borderRadius: '8px', border: '1px solid #ddd', marginBottom: '15px' },
    submitBtn: { background: '#2e7d32', color: '#fff', border: 'none', padding: '12px 30px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }
};

export default QuanLyThongBaoCuDan;
